SELECT * FROM ( SELECT COUNT(*) OVER() AS TOTAL_RECORD_COUNT, TB.* FROM ( SELECT ROW_NUMBER() OVER (ORDER BY A.FRST_REGIST_PNTTM DESC) AS RNUM, A.ROLE_ID, A.ROLE_NAME, A.ROLE_DC, A.ROLE_USEYN, A.ROLE_USER_GUBUN, fn_DetailCodeNm(A.ROLE_USER_GUBUN) AS ROLE_USER_GUBUN_TXT, A.FRST_REGISTER_ID, TO_CHAR(A.FRST_REGIST_PNTTM, 'YYYY-MM-DD') AS FRST_REGIST_PNTTM, TO_CHAR(A.LAST_UPDT_PNTTM, 'YYYY-MM-DD') AS LAST_UPDT_PNTTM, A.LAST_UPDUSR_ID, FN_ROLE_CNT(A.ROLE_ID) AS CHK_MENU FROM TB_ROLEINFO A WHERE 1=1
AND ( A.ROLE_ID LIKE CONCAT('%', #{params.searchKeyword}, '%') OR A.ROLE_NAME LIKE CONCAT('%', #{params.searchKeyword}, '%') )
) TB ) TA ORDER BY TA.RNUM DESC LIMIT #{params.recordCountPerPage} OFFSET #{params.firstIndex}

